804	/**
805	 * Top N produtos do dia da rede, agregando `degust_vendas_diarias` por nome.
806	 * Ranking por quantidade vendida (desempate por valor).
807	 */
808	export function topProductsFromDaily(
809	  rows: DailyProductRow[],
810	  n = 5,
811	): TvTopProduct[] {
812	  const byName = new Map<string, TvTopProduct>();
813	  for (const row of rows) {
814	    let agg = byName.get(row.degust_nome);
815	    if (!agg) {
816	      agg = { nome: row.degust_nome, quantidade: 0, valor: 0 };
817	      byName.set(row.degust_nome, agg);
818	    }
819	    agg.quantidade += row.quantidade ?? 0;
820	    agg.valor += row.valor_total ?? 0;
821	  }
822	  return [...byName.values()]
823	    .sort((a, b) => b.quantidade - a.quantidade || b.valor - a.valor)
824	    .slice(0, n);
825	}
