832	 * (mesma fração). A coluna exibe os {@link TV_CRITICAL_TOP_N} primeiros;
833	 * o drill-down, a lista completa.
834	 */
835	export function sortCriticalItems(items: TvStockAlertItem[]): TvCriticalItem[] {
836	  const missingFraction = (c: TvCriticalItem): number =>
837	    c.minima > 0 ? (c.minima - c.quantidade) / c.minima : 0;
838	  return items
839	    .map<TvCriticalItem>((i) => ({
840	      nome: i.produtoNome,
841	      quantidade: i.quantidade,
