843	      severity: i.zerado ? 'zerado' : 'abaixo-minimo',
844	    }))
845	    .sort((a, b) => {
846	      if (a.severity !== b.severity) return a.severity === 'zerado' ? -1 : 1;
847	      const diff = missingFraction(b) - missingFraction(a);
