async function fetchTopProducts(ctx: TvContext): Promise<TvTopProduct[]> {
  const ids = [...ctx.degustLojaIds];
  if (ids.length === 0) return [];
  // O card é rotulado "TOP 5 PRODUTOS · HOJE": filtra `data` = hoje no fuso
  // LOCAL (mesmo `toIsoDateLocal` usado no resto do hook). Sem vendas hoje →
  // lista vazia (a UI mostra "aguardando vendas do dia"); nunca mostrar
  // ontem com rótulo de hoje.
  const today = toIsoDateLocal(new Date());
  const data = await fetchAllPages((from, to) =>
    supabase
      .from('degust_vendas_diarias')
      .select('degust_nome, quantidade, valor_total')
      .eq('data', today)
      .in('loja_id', ids)
      .order('id')
      .range(from, to),
  );
  return topProductsFromDaily(data, 5);
}

